package cn.binbin.crm;

import jakarta.validation.constraints.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import static cn.binbin.crm.P3Base.map;
import static cn.binbin.crm.TradeService.number;

@Service
public class AiFoundationService {
 public record ModelInput(UUID id,@NotBlank @Pattern(regexp="OPENAI|DEEPSEEK|QWEN") String provider,@NotBlank @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}") String model,@Min(1) @Max(100000000) long inputPriceCentsPerMillion,@Min(1) @Max(100000000) long outputPriceCentsPerMillion,@Min(128) @Max(8192) int maxOutputTokens,boolean active,@Min(0) long expectedVersion){}
 public record PolicyInput(boolean enabled,UUID modelId,@Min(0) @Max(100000000) long monthlyTokenLimit,@Min(0) @Max(100000000) long monthlyBudgetCents,@Min(1000) @Max(20000) int maxInputChars,@Min(128) @Max(8192) int maxOutputTokens,@Min(1) @Max(60) int requestsPerMinute,@Min(0) long expectedVersion){}
 public record PlanInput(@Min(0) @Max(100000000) long aiMonthlyTokenLimit,@Min(0) @Max(100000000) long aiMonthlyBudgetCents,@Min(0) long expectedVersion){}
 public record Booking(UUID id,UUID tenant,UUID member,LocalDate month,Map<String,Object> policy,Map<String,Object> model,long inputBound,long tokens,long cost,boolean invoke){}
 final P3Base b;final AiGateway gateway;
 public AiFoundationService(P3Base b,AiGateway gateway){this.b=b;this.gateway=gateway;}
 private LocalDate month(){return LocalDate.now(ZoneOffset.UTC).withDayOfMonth(1);}
 private AuthService.Actor actor(AuthService.Session s,boolean admin,boolean write){var a=b.auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持访问不包含 AI");if(admin?!a.tenant().roles().contains("TENANT_ADMIN"):!a.p4Access().aiUse())throw ApiError.forbidden("当前角色没有此 AI 权限");if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅到期，AI 仅可查看");b.context(a.tenant().id());return a;}
 private void lock(UUID tenant){b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",tenant),UUID.class);}
 private Map<String,Object> plan(UUID tenant){return b.one("SELECT p.ai_enabled,p.ai_monthly_run_limit,p.ai_monthly_token_limit,p.ai_monthly_budget_cents FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:tenant",map("tenant",tenant));}
 private Map<String,Object> policy(UUID tenant){var rows=b.rows("SELECT * FROM crm_ai_policy WHERE tenant_id=:tenant",map("tenant",tenant));return rows.isEmpty()?map("enabled",false,"modelId",null,"monthlyTokenLimit",500000L,"monthlyBudgetCents",0L,"maxInputChars",8000,"maxOutputTokens",512,"requestsPerMinute",5,"version",0L):rows.getFirst();}
 private Map<String,Object> usage(UUID tenant){var rows=b.rows("SELECT * FROM crm_ai_usage WHERE tenant_id=:tenant AND usage_month=:month",map("tenant",tenant,"month",month()));return rows.isEmpty()?map("usedTokens",0L,"reservedTokens",0L,"estimatedCostCents",0L,"reservedCostCents",0L):rows.getFirst();}
 private List<Map<String,Object>> models(boolean all){return b.rows("SELECT * FROM sys_ai_model"+(all?"":" WHERE active")+" ORDER BY provider,model",Map.of()).stream().map(row->{row.put("keyConfigured",gateway.ready(String.valueOf(row.get("provider"))));return row;}).toList();}
 public Object platform(AuthService.Session s){return b.tx.execute(st->{b.auth.platform(s);return map("providers",gateway.providers(),"models",models(true),"plans",b.rows("SELECT id,name,ai_enabled,ai_monthly_run_limit,ai_monthly_token_limit,ai_monthly_budget_cents,version FROM sys_plan ORDER BY code",Map.of()),"currency","CNY","pricingNotice","参考费用按人工录入的人民币单价估算，不代替供应商账单。密钥只在服务器配置，不返回页面。");});}
 public Object saveModel(AuthService.Session s,ModelInput i,UUID trace){return b.tx.execute(st->{b.auth.platform(s);gateway.endpoint(i.provider());UUID id=i.id()==null?UUID.randomUUID():i.id();var p=map("id",id,"provider",i.provider(),"model",i.model(),"input",i.inputPriceCentsPerMillion(),"output",i.outputPriceCentsPerMillion(),"max",i.maxOutputTokens(),"active",i.active(),"version",i.expectedVersion());try{int n=i.id()==null?b.db.update("INSERT INTO sys_ai_model(id,provider,model,input_price_cents_per_million,output_price_cents_per_million,max_output_tokens,active) VALUES(:id,:provider,:model,:input,:output,:max,:active)",p):b.db.update("UPDATE sys_ai_model SET provider=:provider,model=:model,input_price_cents_per_million=:input,output_price_cents_per_million=:output,max_output_tokens=:max,active=:active,version=version+1,updated_at=now() WHERE id=:id AND version=:version",p);if(n!=1)throw ApiError.conflict("模型配置已变化，请刷新");}catch(org.springframework.dao.DuplicateKeyException e){throw ApiError.conflict("该供应商模型已存在");}platformAudit(s,"AI_MODEL_CONFIGURED",id,trace);return map("id",id);});}
 public Object savePlan(AuthService.Session s,UUID id,PlanInput i,UUID trace){return b.tx.execute(st->{b.auth.platform(s);int n=b.db.update("UPDATE sys_plan SET ai_monthly_token_limit=:tokens,ai_monthly_budget_cents=:budget,version=version+1 WHERE id=:id AND version=:version",map("tokens",i.aiMonthlyTokenLimit(),"budget",i.aiMonthlyBudgetCents(),"id",id,"version",i.expectedVersion()));if(n!=1)throw ApiError.conflict("套餐已变化，请刷新");platformAudit(s,"AI_PLAN_BUDGET_CONFIGURED",id,trace);return map("id",id);});}
 private void platformAudit(AuthService.Session s,String action,UUID id,UUID trace){b.db.update("INSERT INTO sys_platform_audit(id,actor_user_id,action,target_id,trace_id) VALUES(:id,:actor,:action,:target,:trace)",map("id",UUID.randomUUID(),"actor",s.userId(),"action",action,"target",id,"trace",trace));}
 public Object overview(AuthService.Session s){return b.tx.execute(st->{var a=actor(s,true,false);return map("policy",policy(a.tenant().id()),"usage",usage(a.tenant().id()),"models",models(false),"plan",plan(a.tenant().id()),"currency","CNY","usageMonth",month(),"masterEnabled",gateway.masterEnabled());});}
 public Object savePolicy(AuthService.Session s,PolicyInput i,UUID trace){return b.tx.execute(st->{var a=actor(s,true,true);lock(a.tenant().id());var old=policy(a.tenant().id());if(number(old,"version")!=i.expectedVersion())throw ApiError.conflict("AI 设置已变化，请刷新");var plan=plan(a.tenant().id());if(i.monthlyTokenLimit()>number(plan,"aiMonthlyTokenLimit")||i.monthlyBudgetCents()>number(plan,"aiMonthlyBudgetCents"))throw ApiError.bad("企业预算不能高于套餐上限");if(i.enabled()&&(!Boolean.TRUE.equals(plan.get("aiEnabled"))||i.modelId()==null||i.monthlyBudgetCents()==0||i.monthlyTokenLimit()==0))throw ApiError.bad("启用前请选择模型并设置有效预算");if(i.modelId()!=null){var m=b.one("SELECT * FROM sys_ai_model WHERE id=:id AND active",map("id",i.modelId()));if(i.maxOutputTokens()>number(m,"maxOutputTokens"))throw ApiError.bad("输出上限超过模型配置");}var p=map("tenant",a.tenant().id(),"enabled",i.enabled(),"model",i.modelId(),"tokens",i.monthlyTokenLimit(),"budget",i.monthlyBudgetCents(),"input",i.maxInputChars(),"output",i.maxOutputTokens(),"rate",i.requestsPerMinute());b.db.update("INSERT INTO crm_ai_policy(tenant_id,enabled,model_id,monthly_token_limit,monthly_budget_cents,max_input_chars,max_output_tokens,requests_per_minute,version) VALUES(:tenant,:enabled,:model,:tokens,:budget,:input,:output,:rate,1) ON CONFLICT(tenant_id) DO UPDATE SET enabled=excluded.enabled,model_id=excluded.model_id,monthly_token_limit=excluded.monthly_token_limit,monthly_budget_cents=excluded.monthly_budget_cents,max_input_chars=excluded.max_input_chars,max_output_tokens=excluded.max_output_tokens,requests_per_minute=excluded.requests_per_minute,version=crm_ai_policy.version+1,updated_at=now()",p);b.audit(a,"AI_POLICY_UPDATED","AI_POLICY",a.tenant().id(),i.expectedVersion()+1,trace);return overview(s);});}
 public Map<String,Object> status(AuthService.Session s){return b.tx.execute(st->{var a=actor(s,false,false);var p=policy(a.tenant().id());var plan=plan(a.tenant().id());var m=p.get("modelId")==null?map():b.one("SELECT * FROM sys_ai_model WHERE id=:id",map("id",p.get("modelId")));boolean configured=Boolean.TRUE.equals(p.get("enabled"))&&Boolean.TRUE.equals(m.get("active"))&&gateway.ready(String.valueOf(m.get("provider")));long used=b.db.queryForObject("SELECT coalesce((SELECT ai_runs FROM sys_usage_monthly WHERE tenant_id=:tenant AND usage_month=:month),0)",map("tenant",a.tenant().id(),"month",month()),Long.class);return map("configured",configured,"provider",m.getOrDefault("provider",""),"model",m.getOrDefault("model",""),"tenantEnabled",p.get("enabled"),"planEnabled",plan.get("aiEnabled"),"monthlyLimit",plan.get("aiMonthlyRunLimit"),"monthlyUsed",used,"usage",usage(a.tenant().id()),"monthlyTokenLimit",Math.min(number(p,"monthlyTokenLimit"),number(plan,"aiMonthlyTokenLimit")),"monthlyBudgetCents",Math.min(number(p,"monthlyBudgetCents"),number(plan,"aiMonthlyBudgetCents")),"dataPolicy","仅发送经本次人工确认的白名单字段；自由文本、补充要求和输出均执行联系方式、证件及凭据脱敏。AI 生成建议与草稿；仅线索与跟进草稿可经人工编辑、二次确认后按原业务权限保存。");});}
 public Object preview(AuthService.Session s,String hash,String prompt){return b.tx.execute(st->{var a=actor(s,false,true);lock(a.tenant().id());var p=policy(a.tenant().id());var m=p.get("modelId")==null?map():b.one("SELECT * FROM sys_ai_model WHERE id=:id",map("id",p.get("modelId")));long recent=b.db.queryForObject("SELECT count(*) FROM sys_idempotency_request WHERE tenant_id=:tenant AND operation='ai.preview' AND created_at>now()-interval '1 minute'",map("tenant",a.tenant().id()),Long.class);if(recent>=20)throw new ApiError(HttpStatus.TOO_MANY_REQUESTS,"AI_PREVIEW_RATE_LIMITED","预览过于频繁，请稍后重试");String token=Crypto.token();String bound=Crypto.hash(hash+"/"+p.get("version")+"/"+m.get("id")+"/"+m.get("version"));b.db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,'ai.preview',:key,:hash)",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"key",Crypto.hash(token),"hash",bound));return map("confirmationToken",token,"expiresAt",Instant.now().plusSeconds(300),"promptPreview",prompt,"provider",m.getOrDefault("provider","未配置"),"model",m.getOrDefault("model","未配置"));});}
 public Booking reserve(AuthService.Session s,AiService.GenerateInput i,String key,String hash,String preview,String prompt,UUID trace){return b.tx.execute(st->{var a=actor(s,false,true);lock(a.tenant().id());UUID tenant=a.tenant().id(),member=a.tenant().memberId();var params=map("tenant",tenant,"member",member,"key",key);var prior=b.rows("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation='ai.generate' AND request_key=:key",params);if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("requestHash")))throw ApiError.conflict("同一请求编号不能提交不同内容");return new Booking((UUID)prior.getFirst().get("resultId"),tenant,member,month(),map(),map(),0,0,0,false);}var p=policy(tenant);var plan=plan(tenant);if(!Boolean.TRUE.equals(plan.get("aiEnabled")))throw ApiError.forbidden("当前套餐未启用 AI");var m=p.get("modelId")==null?map():b.one("SELECT * FROM sys_ai_model WHERE id=:id",map("id",p.get("modelId")));if(i.confirmationToken()==null||!i.confirmationToken().matches("[A-Za-z0-9_-]{43}"))throw ApiError.bad("请先预览脱敏内容并确认本次发送");String bound=Crypto.hash(hash+"/"+p.get("version")+"/"+m.get("id")+"/"+m.get("version"));var confirmations=b.rows("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation='ai.preview' AND request_key=:key AND created_at>now()-interval '5 minutes' FOR UPDATE",map("tenant",tenant,"member",member,"key",Crypto.hash(i.confirmationToken())));if(confirmations.isEmpty()||confirmations.getFirst().get("resultId")!=null||!bound.equals(confirmations.getFirst().get("requestHash")))throw ApiError.conflict("发送确认已使用、过期或资料配置已变化，请重新预览");boolean configured=Boolean.TRUE.equals(p.get("enabled"))&&Boolean.TRUE.equals(m.get("active"))&&gateway.ready(String.valueOf(m.get("provider")));long input=prompt.getBytes(StandardCharsets.UTF_8).length+2048L,tokens=0,cost=0;
  if(configured){if(prompt.length()>number(p,"maxInputChars"))throw ApiError.bad("业务上下文超出企业输入上限，请缩短说明");var usage=usage(tenant);int out=(int)Math.min(number(p,"maxOutputTokens"),number(m,"maxOutputTokens"));p.put("maxOutputTokens",out);tokens=input+out;cost=AiRedaction.cost(input,out,number(m,"inputPriceCentsPerMillion"),number(m,"outputPriceCentsPerMillion"));long runs=b.db.queryForObject("SELECT coalesce((SELECT ai_runs FROM sys_usage_monthly WHERE tenant_id=:tenant AND usage_month=:month),0)",map("tenant",tenant,"month",month()),Long.class);if(runs>=number(plan,"aiMonthlyRunLimit"))throw new ApiError(HttpStatus.CONFLICT,"AI_QUOTA_EXCEEDED","本月 AI 调用额度已用完");if(number(usage,"usedTokens")+number(usage,"reservedTokens")+tokens>Math.min(number(p,"monthlyTokenLimit"),number(plan,"aiMonthlyTokenLimit")))throw new ApiError(HttpStatus.CONFLICT,"AI_TOKEN_BUDGET_EXCEEDED","剩余 Token 预算不足以预留本次调用");if(number(usage,"estimatedCostCents")+number(usage,"reservedCostCents")+cost>Math.min(number(p,"monthlyBudgetCents"),number(plan,"aiMonthlyBudgetCents")))throw new ApiError(HttpStatus.CONFLICT,"AI_COST_BUDGET_EXCEEDED","剩余参考费用预算不足以预留本次调用");long recent=b.db.queryForObject("SELECT count(*) FROM crm_ai_run WHERE tenant_id=:tenant AND status<>'BLOCKED' AND created_at>now()-interval '1 minute'",map("tenant",tenant),Long.class);if(recent>=number(p,"requestsPerMinute"))throw new ApiError(HttpStatus.TOO_MANY_REQUESTS,"AI_RATE_LIMITED","AI 请求过于频繁，请稍后重试");b.db.update("INSERT INTO crm_ai_usage(tenant_id,usage_month,reserved_tokens,reserved_cost_cents) VALUES(:tenant,:month,:tokens,:cost) ON CONFLICT(tenant_id,usage_month) DO UPDATE SET reserved_tokens=crm_ai_usage.reserved_tokens+:tokens,reserved_cost_cents=crm_ai_usage.reserved_cost_cents+:cost",map("tenant",tenant,"month",month(),"tokens",tokens,"cost",cost));b.db.update("INSERT INTO sys_usage_monthly(tenant_id,usage_month,ai_runs) VALUES(:tenant,:month,1) ON CONFLICT(tenant_id,usage_month) DO UPDATE SET ai_runs=sys_usage_monthly.ai_runs+1,updated_at=now()",map("tenant",tenant,"month",month()));}
  UUID id=UUID.randomUUID();String entity=AiScenarioService.task(i.taskType()).entityType();var values=map("id",id,"tenant",tenant,"member",member,"task",i.taskType(),"entity",entity,"record",i.recordId(),"provider",m.getOrDefault("provider","UNCONFIGURED"),"model",m.getOrDefault("model",""),"state",configured?"PENDING":"BLOCKED","hash",hash,"preview",preview,"error",configured?null:"AI_PROVIDER_NOT_CONFIGURED","modelId",m.get("id"),"mv",m.get("version"),"pv",p.get("version"),"inputRate",m.getOrDefault("inputPriceCentsPerMillion",0),"outputRate",m.getOrDefault("outputPriceCentsPerMillion",0),"tokens",tokens,"cost",cost);b.db.update("INSERT INTO crm_ai_run(id,tenant_id,member_id,task_type,entity_type,entity_id,provider,model,status,prompt_hash,context_preview,error_code,model_id,model_version,policy_version,input_price_cents_per_million,output_price_cents_per_million,reserved_tokens,reserved_cost_cents,completed_at) VALUES(:id,:tenant,:member,:task,:entity,:record,:provider,:model,:state,:hash,:preview,:error,:modelId,:mv,:pv,:inputRate,:outputRate,:tokens,:cost,CASE WHEN :state='BLOCKED' THEN now() END)",values);b.db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash,result_id) VALUES(:tenant,:member,'ai.generate',:key,:hash,:id)",map("tenant",tenant,"member",member,"key",key,"hash",hash,"id",id));b.db.update("UPDATE sys_idempotency_request SET result_id=:id WHERE tenant_id=:tenant AND member_id=:member AND operation='ai.preview' AND request_key=:key",map("id",id,"tenant",tenant,"member",member,"key",Crypto.hash(i.confirmationToken())));b.audit(a,configured?"AI_USAGE_RESERVED":"AI_REQUEST_BLOCKED","AI_RUN",id,0,trace);return new Booking(id,tenant,member,month(),p,m,input,tokens,cost,configured);
 });}
 public boolean claim(AuthService.Session s,Booking booking){return b.tx.execute(st->{var a=actor(s,false,true);lock(a.tenant().id());long live=b.db.queryForObject("SELECT count(*) FROM auth_session s JOIN iam_user u ON u.id=s.user_id WHERE s.id=:id AND s.revoked_at IS NULL AND s.expires_at>now() AND u.status='ACTIVE' AND u.auth_version=s.user_auth_version",map("id",s.id()),Long.class);if(live!=1)throw ApiError.unauthorized();var p=policy(booking.tenant());var m=b.one("SELECT * FROM sys_ai_model WHERE id=:id",map("id",booking.model().get("id")));var plan=plan(booking.tenant());if(!Boolean.TRUE.equals(p.get("enabled"))||!Boolean.TRUE.equals(plan.get("aiEnabled"))||!Boolean.TRUE.equals(m.get("active"))||number(p,"version")!=number(booking.policy(),"version")||number(m,"version")!=number(booking.model(),"version")||!gateway.ready(String.valueOf(m.get("provider"))))throw ApiError.conflict("AI 配置已变化，本次调用已停止");var currentUsage=usage(booking.tenant());if(number(currentUsage,"usedTokens")+number(currentUsage,"reservedTokens")>Math.min(number(p,"monthlyTokenLimit"),number(plan,"aiMonthlyTokenLimit"))||number(currentUsage,"estimatedCostCents")+number(currentUsage,"reservedCostCents")>Math.min(number(p,"monthlyBudgetCents"),number(plan,"aiMonthlyBudgetCents")))throw ApiError.conflict("套餐预算已变化，本次调用已停止");return b.db.update("UPDATE crm_ai_run SET status='RUNNING',started_at=now() WHERE tenant_id=:tenant AND id=:id AND status='PENDING'",map("tenant",booking.tenant(),"id",booking.id()))==1;});}
 public void finish(Booking k,AiGateway.Reply reply,String error,boolean uncertain,UUID trace){b.tx.executeWithoutResult(st->{b.context(k.tenant());lock(k.tenant());boolean success=reply!=null;boolean estimated=uncertain||(success&&!reply.usageReported());long input=success&&reply.usageReported()?reply.inputTokens():0,output=success&&reply.usageReported()?reply.outputTokens():0;long tokens=estimated?k.tokens():input+output,cost=estimated?k.cost():AiRedaction.cost(input,output,number(k.model(),"inputPriceCentsPerMillion"),number(k.model(),"outputPriceCentsPerMillion"));int changed=b.db.update("UPDATE crm_ai_run SET status=:state,result_text=:result,input_tokens=:input,output_tokens=:output,estimated_cost_cents=:cost,usage_estimated=:estimated,error_code=:error,reserved_tokens=0,reserved_cost_cents=0,completed_at=now() WHERE tenant_id=:tenant AND id=:id AND status IN('PENDING','RUNNING')",map("state",success?"SUCCEEDED":"FAILED","result",success?reply.text():null,"input",input,"output",output,"cost",cost,"estimated",estimated,"error",error,"tenant",k.tenant(),"id",k.id()));if(changed!=1)return;b.db.update("UPDATE crm_ai_usage SET used_tokens=used_tokens+:tokens,estimated_cost_cents=estimated_cost_cents+:cost,reserved_tokens=reserved_tokens-:reservedTokens,reserved_cost_cents=reserved_cost_cents-:reservedCost WHERE tenant_id=:tenant AND usage_month=:month",map("tokens",tokens,"cost",cost,"reservedTokens",k.tokens(),"reservedCost",k.cost(),"tenant",k.tenant(),"month",k.month()));if(!success&&!uncertain)b.db.update("UPDATE sys_usage_monthly SET ai_runs=greatest(ai_runs-1,0),updated_at=now() WHERE tenant_id=:tenant AND usage_month=:month",map("tenant",k.tenant(),"month",k.month()));b.db.update("INSERT INTO sys_audit_log(id,tenant_id,actor_member_id,action,entity_type,entity_id,business_version,trace_id) VALUES(:audit,:tenant,:member,:action,'AI_RUN',:id,0,:trace)",map("audit",UUID.randomUUID(),"tenant",k.tenant(),"member",k.member(),"action",success?"AI_COMPLETED":estimated?"AI_COST_UNCERTAIN":"AI_FAILED","id",k.id(),"trace",trace));});}
}
